package io.colorsand.core

/** The outcome of [Solver.search]. */
sealed interface SolveResult {
    /** [moves] solve the board (empty if it was already solved). */
    data class Solution(val moves: List<Move>) : SolveResult

    /** Every reachable board was explored and none is solved: the board cannot be won. */
    data object Unsolvable : SolveResult

    /** The search hit its state budget before finding a solution or exhausting the board. */
    data object GaveUp : SolveResult
}

/**
 * Depth-first solver with move ordering: finds *a* solution quickly, not necessarily the shortest.
 *
 * Used for hints and to check that levels are solvable. Tube order does not matter for solvability,
 * so boards that are permutations of each other are explored only once. With an unlimited budget the
 * search is exhaustive, so whether it finds a solution does not depend on the move ordering.
 */
object Solver {
    const val DEFAULT_MAX_STATES = 200_000

    /** Searches for a solution, exploring at most [maxStates] distinct boards. */
    fun search(board: Board, maxStates: Int = DEFAULT_MAX_STATES): SolveResult {
        if (board.isSolved) return SolveResult.Solution(emptyList())
        val seen = HashSet<Any>().apply { add(key(board)) }
        val path = ArrayList<Move>()
        // Each frame is a board and the moves from it that are still to be tried.
        val stack = ArrayList<Pair<Board, ArrayDeque<Move>>>()
        stack.add(board to ArrayDeque(orderedMoves(board)))

        while (stack.isNotEmpty()) {
            val (current, remaining) = stack.last()
            val move = remaining.removeFirstOrNull()
            if (move == null) {
                stack.removeLast()
                path.removeLastOrNull()
                continue
            }
            val next = current.pour(move.from, move.to)!!.first
            if (!seen.add(key(next))) continue
            path.add(move)
            if (next.isSolved) return SolveResult.Solution(path)
            if (seen.size >= maxStates) return SolveResult.GaveUp
            stack.add(next to ArrayDeque(orderedMoves(next)))
        }
        return SolveResult.Unsolvable
    }

    /** The pours that solve [board], or null if it is unsolvable or the search gave up. */
    fun solve(board: Board, maxStates: Int = DEFAULT_MAX_STATES): List<Move>? =
        (search(board, maxStates) as? SolveResult.Solution)?.moves

    fun isSolvable(board: Board, maxStates: Int = DEFAULT_MAX_STATES): Boolean = solve(board, maxStates) != null

    /** Legal, non-pointless moves, most promising first. */
    private fun orderedMoves(board: Board): List<Move> =
        board.legalMoves()
            .filterNot { isPointless(board, it) }
            .sortedByDescending { score(board, it) }

    /** Moving a whole single-colored tube into an empty tube of the same size changes nothing. */
    private fun isPointless(board: Board, move: Move): Boolean {
        val source = board.tubes[move.from]
        val target = board.tubes[move.to]
        return target.isEmpty && target.capacity == source.capacity && source.isUniform && move.amount == source.size
    }

    private fun score(board: Board, move: Move): Int {
        val source = board.tubes[move.from]
        val target = board.tubes[move.to]
        var score = 0
        if (!target.isEmpty) score += 4 // stacking onto matching color beats using up an empty tube
        if (target.isUniform) score += 2 // builds toward a finished tube
        if (move.amount == source.topRunLength) score += 1 // the whole run moved, nothing left split
        if (move.amount == source.size) score += 1 // empties the source
        return score
    }

    /** Largest capacity whose tubes fit in a Long: 4 bits of capacity plus 4 bits per unit. */
    private const val MAX_PACKED_CAPACITY = 14

    /** A key that is equal for boards that are permutations of each other. */
    private fun key(board: Board): Any {
        if (board.tubes.any { it.capacity > MAX_PACKED_CAPACITY }) {
            return board.tubes.map { "${it.capacity}:${it.encode()}" }.sorted().joinToString("|")
        }
        val packed = LongArray(board.tubes.size) { i ->
            val tube = board.tubes[i]
            tube.layers.fold(tube.capacity.toLong()) { acc, color -> acc * 16 + color.ordinal + 1 }
        }
        packed.sort()
        return PackedKey(packed)
    }

    private class PackedKey(val tubes: LongArray) {
        override fun equals(other: Any?): Boolean = other is PackedKey && tubes.contentEquals(other.tubes)
        override fun hashCode(): Int = tubes.contentHashCode()
    }
}
