/** The whole game: level header, tubes, controls, and the level-complete card. */
@Composable
fun App(store: ProgressStore) {
    val game = rememberSaveable(saver = GameController.saver(store)) { GameController(store) }
    val pours = rememberPourAnimation(game)
    var chosen by remember { mutableStateOf(storedPalette(store)) }
    var custom by remember { mutableStateOf(CustomScheme.decode(store.customColors)) }
    var paw by remember { mutableStateOf(PawKind.byName(store.paw)) }
    var picking by remember { mutableStateOf(false) }
    var showLevels by rememberSaveable { mutableStateOf(false) }
    ColorSandTheme(chosen) {
        val palette = LocalPalette.current
        Box(
            Modifier
                .fillMaxSize()
                .background(Brush.verticalGradient(listOf(palette.backgroundTop, palette.backgroundBottom)))
                .windowInsetsPadding(WindowInsets.safeDrawing),
        ) {
            Column(
                Modifier.fillMaxSize().padding(16.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) {
                Header(game, onColors = { picking = true }, onLevels = { showLevels = true })
                CompositionLocalProvider(LocalPawKind provides paw) { BoardView(game, Modifier.weight(1f).fillMaxWidth(), pours) }
                NoticeLine(game)
                Controls(game)
            }
            // Let the last grains land before the level-complete card comes up.
            if (game.isSolved && !pours.isRunning) LevelComplete(game)
            if (picking) {
                PalettePicker(
                    current = chosen,
                    custom = custom,
                    onPick = { chosen = it; store.palette = it.name },
                    onCustom = { scheme, save ->
                        custom = scheme
                        chosen = scheme.palette()
                        if (save) store.customColors = scheme.encode()
                    },
                    onDismiss = { picking = false },
                    more = { PawPicker(paw, onPick = { paw = it; store.paw = it.name }) },
                )
            }
            if (showLevels) LevelSelector(game, onClose = { showLevels = false })
        }
    }
}

@Composable
private fun Header(game: GameController, onColors: () -> Unit, onLevels: () -> Unit) {
    val palette = LocalPalette.current
    Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
        // Moves sit under the level number so both header buttons fit on a narrow phone.
        Column(Modifier.weight(1f)) {
            Text("Level ${game.levelNumber}", color = palette.accent, fontSize = 24.sp, fontWeight = FontWeight.Bold, maxLines = 1)
            Text("Moves ${game.moveCount}", color = palette.dimText, fontSize = 14.sp, maxLines = 1)
        }
        Spacer(Modifier.width(8.dp))
        PaletteButton(onColors)
        Spacer(Modifier.width(8.dp))
        LevelsButton(onLevels)
    }
}

@Composable
private fun NoticeLine(game: GameController) {
    val text = when {
        game.isSolved -> null
        game.isStuck -> "No moves left. Undo or restart."
        game.notice == Notice.DEAD_END -> "This can't be solved from here. Undo or restart."
        game.notice == Notice.NO_HINT -> "No hint found. Try a few moves."
        game.hint != null -> "Hint: pour the raised tube into the other glowing one."
        else -> null
    }
    Box(Modifier.height(40.dp), contentAlignment = Alignment.Center) {
        if (text != null) Text(text, color = LocalPalette.current.highlight, textAlign = TextAlign.Center, fontSize = 14.sp)
    }
}

@Composable
private fun Controls(game: GameController) {
    Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
        OutlinedButton(onClick = game::undo, enabled = game.canUndo && !game.isSolved) { Text("Undo") }
        OutlinedButton(onClick = game::restart, enabled = game.canUndo && !game.isSolved) { Text("Restart") }
        Button(onClick = game::showHint, enabled = !game.isSolved && !game.isStuck) { Text("Hint") }
    }
}
