/** How a tube is highlighted. */
enum class TubeHighlight { NONE, SELECTED, HINT_FROM, HINT_TO }

/**
 * Sand on its way in or out during a pour: [units] (read while drawing, so it can change every frame) more units
 * of [color] drawn on top of the tube's own layers. A fraction of a unit fills part of a layer.
 */
class PouringSand(val color: SandColor, val units: () -> Float)

/**
 * One glass tube with its sand, drawn on a canvas. Lifts a little as a hint's source (the paw lifts a selected one).
 * A [hidden] tube keeps its place and still takes taps, but isn't drawn (the pour animation is holding it).
 */
@Composable
fun TubeView(
    tube: Tube,
    highlight: TubeHighlight,
    width: Dp,
    onTap: () -> Unit,
    modifier: Modifier = Modifier,
    pouring: PouringSand? = null,
    hidden: Boolean = false,
) {
    val lift by animateDpAsState(
        when (highlight) {
            TubeHighlight.HINT_FROM -> -width * 0.2f
            else -> 0.dp
        },
    )
    val description = "Tube: " + tube.layers.joinToString(", ") { it.name.lowercase() }.ifEmpty { "empty" }
    val palette = LocalPalette.current
    Canvas(
        modifier
            .offset(y = lift)
            .size(width, width * TUBE_ASPECT)
            .semantics { contentDescription = description }
            .clickable(interactionSource = remember { MutableInteractionSource() }, indication = null, onClick = onTap),
    ) {
        if (!hidden) drawTube(tube, highlight, palette, pouring)
    }
}

const val TUBE_ASPECT = 3.6f

/** Height of one unit of sand in a tube [width] by [height]. Sand fills from the bottom; the top 8% is the neck. */
internal fun sandUnitHeight(width: Float, height: Float, capacity: Int): Float =
    (height - width * 0.03f - height * 0.08f) / capacity

/** Height above the tube's bottom edge of the sand surface when the tube holds [units] of sand. */
internal fun sandLevel(width: Float, height: Float, capacity: Int, units: Float): Float =
    width * 0.03f + sandUnitHeight(width, height, capacity) * units

private fun DrawScope.drawTube(tube: Tube, highlight: TubeHighlight, palette: Palette, pouring: PouringSand?) {
    val stroke = size.width * 0.06f
    val inset = stroke / 2
    val glass = RoundRect(
        left = inset,
        top = inset,
        right = size.width - inset,
        bottom = size.height - inset,
        topLeftCornerRadius = CornerRadius(size.width * 0.12f),
        topRightCornerRadius = CornerRadius(size.width * 0.12f),
        bottomLeftCornerRadius = CornerRadius(size.width / 2),
        bottomRightCornerRadius = CornerRadius(size.width / 2),
    )
    val glassPath = Path().apply { addRoundRect(glass) }

    drawPath(glassPath, palette.glass)

    val unit = sandUnitHeight(size.width, size.height, tube.capacity)
    fun layer(i: Int, color: SandColor) {
        val bottom = size.height - inset - unit * i
        val top = bottom - unit
        drawRect(palette.sand(color), topLeft = Offset(0f, top), size = Size(size.width, unit + 0.5f))
        drawGrain(top, unit, seed = color.ordinal * 31 + i)
    }
    clipPath(glassPath) {
        tube.layers.forEachIndexed { i, color -> layer(i, color) }
        // Pouring sand: whole layers, then the bottom part of the last one. Its grains don't move as it fills,
        // so the texture runs on seamlessly into the finished layer.
        var units = (pouring?.units?.invoke() ?: 0f).coerceAtMost((tube.capacity - tube.size).toFloat())
        var i = tube.size
        while (units > 0f) {
            val bottom = size.height - inset - unit * i
            clipRect(top = bottom - unit * units.coerceAtMost(1f)) { layer(i, pouring!!.color) }
            units -= 1f
            i++
        }
    }

    val outline = when (highlight) {
        TubeHighlight.SELECTED -> palette.selected
        TubeHighlight.HINT_FROM, TubeHighlight.HINT_TO -> palette.highlight
        TubeHighlight.NONE -> if (tube.isFull && tube.isSorted) palette.done else palette.glassOutline
    }
    drawPath(glassPath, outline, style = Stroke(width = if (highlight == TubeHighlight.NONE) stroke else stroke * 1.6f))

    // A soft highlight down the left side makes it read as glass.
    drawLine(
        palette.glassShine,
        start = Offset(size.width * 0.25f, size.height * 0.1f),
        end = Offset(size.width * 0.25f, size.height * 0.8f),
        strokeWidth = size.width * 0.07f,
    )
}

/** Speckles of lighter and darker grains so a layer reads as sand rather than paint. */
private fun DrawScope.drawGrain(top: Float, height: Float, seed: Int) {
    var state = seed * 1103515245 + 12345
    fun next(): Float {
        state = state * 1103515245 + 12345
        return ((state ushr 8) and 0xFFFF) / 65535f
    }
    val grain = size.width * 0.03f
    repeat(70) {
        val shade = if (next() > 0.5f) Color.White.copy(alpha = 0.2f) else Color.Black.copy(alpha = 0.18f)
        val side = grain * (0.5f + next())
        drawRect(shade, topLeft = Offset(next() * size.width, top + next() * (height - side)), size = Size(side, side))
    }
}
