/** The "Paw" row of the Colors sheet: a small picture of every paw. Tapping one applies it at once. */
@Composable
fun PawPicker(current: PawKind, onPick: (PawKind) -> Unit) {
    val palette = LocalPalette.current
    Column(Modifier.padding(top = 6.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text("Paw", fontSize = 20.sp, fontWeight = FontWeight.Bold, color = palette.accent)
            Spacer(Modifier.weight(1f))
            Text(current.label, color = palette.dimText, fontSize = 13.sp)
        }
        // Two rows of four, so each tile stays a comfortable touch target (over 60dp) even on a 320dp phone.
        Column(Modifier.fillMaxWidth().padding(top = 8.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
            for (row in PawKind.entries.chunked(4)) {
                Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                    for (kind in row) {
                        PawOption(kind, isCurrent = kind == current, onClick = { onPick(kind) }, modifier = Modifier.weight(1f))
                    }
                }
            }
        }
    }
}

/** One paw on a little tile of the board's background, with a bit of its arm. */
@Composable
private fun PawOption(kind: PawKind, isCurrent: Boolean, onClick: () -> Unit, modifier: Modifier) {
    val palette = LocalPalette.current
    val look = pawLook(kind, palette)
    Surface(
        onClick = onClick,
        modifier = modifier.aspectRatio(1.2f).semantics {
            selected = isCurrent
            contentDescription = "${kind.label} paw"
        },
        shape = RoundedCornerShape(10.dp),
        color = palette.backgroundBottom,
        border = if (isCurrent) BorderStroke(3.dp, palette.highlight) else BorderStroke(1.dp, palette.glassOutline),
    ) {
        Canvas(Modifier.fillMaxSize()) {
            val w = size.height * 0.5f
            val grip = Offset(size.width / 2, size.height * 0.42f)
            // The paw as it holds a tube from the right, turned upright: its arm then hangs down.
            rotate(90f, pivot = grip) {
                drawForearm(kind, look, grip, w, kind.arm * w, side = 1, rise = 0f, edge = grip.x + size.height)
                // As an icon the palm with its pads reads best; on the board the paw shows its back.
                drawPaw(kind, look, grip, w, pawRotation(side = 1), pads = true)
            }
        }
    }
}
