/** How many locked levels the picker shows after the first unsolved one, as a peek at what's ahead. */
private const val LOCKED_PREVIEW = 12

/**
 * Full-screen level picker. Solved levels carry a check, the first unsolved one is highlighted, and a few
 * locked ones follow. Picking an unlocked level opens it and closes the picker.
 */
@Composable
fun LevelSelector(game: GameController, onClose: () -> Unit) {
    DismissOnBack(onBack = onClose)
    val palette = LocalPalette.current
    val unlocked = game.unlockedLevel
    val count = unlocked + LOCKED_PREVIEW
    val gridState = rememberLazyGridState()
    LaunchedEffect(Unit) {
        // Bring the level being played to the middle of the grid.
        val target = game.levelNumber - 1
        gridState.scrollToItem(target)
        val info = gridState.layoutInfo
        val tile = info.visibleItemsInfo.firstOrNull { it.index == target } ?: return@LaunchedEffect
        val viewport = info.viewportEndOffset - info.viewportStartOffset
        gridState.scrollBy((tile.offset.y - (viewport - tile.size.height) / 2).toFloat())
    }
    Box(
        Modifier
            .fillMaxSize()
            .background(Brush.verticalGradient(listOf(palette.backgroundTop, palette.backgroundBottom)))
            // Swallow taps so nothing underneath reacts.
            .clickable(remember { MutableInteractionSource() }, indication = null) {}
            .windowInsetsPadding(WindowInsets.safeDrawing),
        contentAlignment = Alignment.TopCenter,
    ) {
        Column(Modifier.widthIn(max = 640.dp).fillMaxSize().padding(16.dp)) {
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Text("Levels", color = palette.accent, fontSize = 24.sp, fontWeight = FontWeight.Bold)
                Spacer(Modifier.weight(1f))
                CloseButton(onClose)
            }
            Spacer(Modifier.height(4.dp))
            Text("${unlocked - 1} solved", color = palette.dimText, fontSize = 14.sp)
            Spacer(Modifier.height(12.dp))
            LazyVerticalGrid(
                columns = GridCells.Adaptive(minSize = 68.dp),
                state = gridState,
                modifier = Modifier.weight(1f).fillMaxWidth(),
                contentPadding = PaddingValues(vertical = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                items(count, key = { it + 1 }) { index ->
                    val number = index + 1
                    LevelTile(
                        number = number,
                        solved = number < unlocked,
                        current = number == unlocked,
                        locked = number > unlocked,
                        open = number == game.levelNumber,
                        onClick = {
                            if (game.goToLevel(number)) onClose()
                        },
                    )
                }
            }
        }
    }
}

/** Header button that opens the level picker; sized to sit next to [PaletteButton]. */
@Composable
fun LevelsButton(onClick: () -> Unit) {
    val palette = LocalPalette.current
    OutlinedButton(
        onClick = onClick,
        modifier = Modifier.height(32.dp),
        contentPadding = PaddingValues(horizontal = 10.dp),
        border = BorderStroke(1.dp, palette.glassOutline),
    ) {
        Text("Levels", fontSize = 13.sp)
    }
}

@Composable
private fun CloseButton(onClick: () -> Unit) {
    val palette = LocalPalette.current
    Box(
        Modifier
            .size(40.dp)
            .clip(CircleShape)
            .background(palette.surface)
            .clickable(role = Role.Button, onClick = onClick)
            .semantics { contentDescription = "Close levels" },
        contentAlignment = Alignment.Center,
    ) {
        Canvas(Modifier.size(14.dp)) {
            val stroke = 2.dp.toPx()
            drawLine(palette.text, Offset.Zero, Offset(size.width, size.height), stroke, StrokeCap.Round)
            drawLine(palette.text, Offset(size.width, 0f), Offset(0f, size.height), stroke, StrokeCap.Round)
        }
    }
}

@Composable
private fun LevelTile(number: Int, solved: Boolean, current: Boolean, locked: Boolean, open: Boolean, onClick: () -> Unit) {
    val palette = LocalPalette.current
    val shape = RoundedCornerShape(14.dp)
    val fill = when {
        current -> palette.accent
        locked -> palette.surface.copy(alpha = 0.45f)
        else -> palette.surface
    }
    val textColor = when {
        current -> palette.onAccent
        locked -> palette.dimText.copy(alpha = 0.5f)
        else -> palette.text
    }
    var modifier = Modifier.aspectRatio(1f).clip(shape).background(fill)
    if (open) modifier = modifier.border(3.dp, palette.highlight, shape)
    if (!locked) modifier = modifier.clickable(role = Role.Button, onClick = onClick)
    // Read the tile as one item with its number, its "playing" label and its state, which is otherwise only drawn.
    modifier = modifier.semantics(mergeDescendants = true) {
        stateDescription = when {
            solved -> "solved"
            current -> "next to solve"
            else -> "locked"
        }
        if (locked) disabled()
    }
    Box(modifier, contentAlignment = Alignment.Center) {
        if (locked) {
            LockIcon(textColor, Modifier.padding(bottom = 10.dp).size(width = 14.dp, height = 16.dp))
            Text("$number", color = textColor, fontSize = 12.sp, modifier = Modifier.align(Alignment.BottomCenter).padding(bottom = 6.dp))
        } else {
            Text("$number", color = textColor, fontSize = 22.sp, fontWeight = FontWeight.Bold)
        }
        if (solved) CheckIcon(palette.done, Modifier.align(Alignment.TopEnd).padding(6.dp).size(14.dp))
        if (open) {
            Text(
                "playing",
                color = if (current) palette.onAccent else palette.highlight,
                fontSize = 10.sp,
                modifier = Modifier.align(Alignment.BottomCenter).padding(bottom = 5.dp),
            )
        }
    }
}

@Composable
private fun CheckIcon(color: Color, modifier: Modifier) {
    Canvas(modifier) {
        val path = Path().apply {
            moveTo(size.width * 0.12f, size.height * 0.55f)
            lineTo(size.width * 0.4f, size.height * 0.82f)
            lineTo(size.width * 0.9f, size.height * 0.2f)
        }
        drawPath(path, color, style = Stroke(2.5.dp.toPx(), cap = StrokeCap.Round, join = StrokeJoin.Round))
    }
}

@Composable
private fun LockIcon(color: Color, modifier: Modifier) {
    Canvas(modifier) {
        val stroke = 2.dp.toPx()
        val bodyTop = size.height * 0.45f
        // Shackle: an arch above the body.
        drawArc(
            color,
            startAngle = 180f,
            sweepAngle = 180f,
            useCenter = false,
            topLeft = Offset(size.width * 0.2f, stroke / 2),
            size = Size(size.width * 0.6f, size.height * 0.6f),
            style = Stroke(stroke),
        )
        drawLine(color, Offset(size.width * 0.2f, size.height * 0.3f), Offset(size.width * 0.2f, bodyTop), stroke)
        drawLine(color, Offset(size.width * 0.8f, size.height * 0.3f), Offset(size.width * 0.8f, bodyTop), stroke)
        drawRoundRect(
            color,
            topLeft = Offset(0f, bodyTop),
            size = Size(size.width, size.height - bodyTop),
            cornerRadius = CornerRadius(2.dp.toPx()),
        )
    }
}
