package io.colorsand.core

import kotlin.random.Random

/**
 * Generates random solvable levels. The same level number always yields the same level on every platform.
 *
 * Changing anything here (the shuffle, the difficulty curve, the seed) changes the levels players already
 * have, so `LevelsTest` pins a few of them.
 */
object LevelGenerator {
    const val CAPACITY = 4
    const val EMPTY_TUBES = 2
    private const val MAX_ATTEMPTS = 1_000

    /**
     * Difficulty curve: one more color every 7 levels, capped by the palette size. It starts at the
     * last hand-made level's color count so there is no drop after the hand-made levels.
     */
    fun colorsFor(number: Int): Int = (7 + number / 7).coerceAtMost(SandColor.entries.size)

    fun generate(number: Int, colors: Int = colorsFor(number), seed: Long = number.toLong()): Level {
        require(number >= 1) { "Level numbers start at 1, was $number" }
        require(colors in 2..SandColor.entries.size) { "colors must be in 2..${SandColor.entries.size}" }
        val random = Random(seed)
        val palette = SandColor.entries.take(colors)
        repeat(MAX_ATTEMPTS) {
            val units = palette.flatMap { color -> List(CAPACITY) { color } }.toMutableList()
            shuffle(units, random)
            val filled = units.chunked(CAPACITY).map { Tube(CAPACITY, it) }
            val board = Board(filled + List(EMPTY_TUBES) { Tube(CAPACITY) })
            // An unlimited budget makes the check exhaustive, so solver tuning can't change which board is picked.
            if (filled.none { it.isSorted } && Solver.isSolvable(board, maxStates = Int.MAX_VALUE)) {
                return Level(number, board)
            }
        }
        error("No solvable level found for level $number with $colors colors")
    }

    /** Fisher-Yates, written out so the result only depends on [Random]'s output, not on library internals. */
    private fun <T> shuffle(list: MutableList<T>, random: Random) {
        for (i in list.lastIndex downTo 1) {
            val j = random.nextInt(i + 1)
            val tmp = list[i]
            list[i] = list[j]
            list[j] = tmp
        }
    }
}
